// Aggregate all processed message IDs into one item.
// Runs ONCE per execution — same pattern used to avoid N sheet reads.
const rows = $input.all();
const processedIds = rows.map(r => r.json.messageId).filter(Boolean);
return [{ json: { processedIds } }];

// Dedup against processed IDs (built once at start of run).
// Also extracts and cleans email fields from the Gmail API payload.
const processedIds = new Set($('Build Processed IDs Set').first().json.processedIds || []);
const results = [];

const findBody = (parts, payload) => {
  for (const part of (parts || [])) {
    if (part.mimeType === 'text/plain' && part.body?.data) {
      return Buffer.from(part.body.data, 'base64').toString('utf8');
    }
    if (part.parts) {
      const nested = findBody(part.parts, null);
      if (nested) return nested;
    }
  }
  if (payload?.body?.data) {
    return Buffer.from(payload.body.data, 'base64').toString('utf8');
  }
  return '';
};

for (const item of $input.all()) {
  const msg = item.json;
  if (processedIds.has(msg.id)) continue;

  const headers = msg.payload?.headers || [];
  const h = name => headers.find(x => x.name.toLowerCase() === name.toLowerCase())?.value || '';

  let body = findBody(msg.payload?.parts, msg.payload);
  // Strip HTML tags and collapse whitespace
  body = body.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  // Truncate to 3000 chars to stay within token limits
  body = body.substring(0, 3000) + (body.length > 3000 ? ' [truncated]' : '');

  results.push({
    json: {
      messageId: msg.id,
      threadId: msg.threadId,
      subject: h('Subject') || '(no subject)',
      from: h('From'),
      to: h('To'),
      date: h('Date'),
      body
    }
  });
}

// Returning [] stops execution cleanly when there are no new emails.
return results;

