const item = $input.first();
const aiRaw = item.json.message?.content || '';

// Restore original email fields (GPT node output overwrites $json)
const email = $('Extract & Filter New Emails').item.json;

let parsed;
try {
  parsed = JSON.parse(aiRaw);
} catch(e) {
  parsed = {
    category: 'OTHER',
    priority: 'MEDIUM',
    summary: 'Could not parse AI response.',
    requires_response: false,
    response_deadline: 'none',
    suggested_assignee: 'none',
    draft_reply: ''
  };
}

// Map AI category to Gmail label ID.
// Replace each placeholder with the actual label ID from your Gmail account.
// To find a label ID: Gmail Settings → Labels → click label → ID is in the URL.
const labelMap = {
  SUPPORT:    'YOUR_LABEL_ID_SUPPORT',
  SALES:      'YOUR_LABEL_ID_SALES',
  HR:         'YOUR_LABEL_ID_HR',
  FINANCE:    'YOUR_LABEL_ID_FINANCE',
  LEGAL:      'YOUR_LABEL_ID_LEGAL',
  INTERNAL:   'YOUR_LABEL_ID_INTERNAL',
  NEWSLETTER: 'YOUR_LABEL_ID_NEWSLETTER',
  SPAM:       'YOUR_LABEL_ID_SPAM',
  OTHER:      'YOUR_LABEL_ID_OTHER'
};

const gmailLabelId = labelMap[parsed.category] ?? labelMap['OTHER'];

return [{
  json: {
    ...email,
    category: parsed.category,
    priority: parsed.priority,
    summary: parsed.summary,
    requires_response: parsed.requires_response,
    response_deadline: parsed.response_deadline,
    suggested_assignee: parsed.suggested_assignee,
    draft_reply: parsed.draft_reply || '',
    gmailLabelId
  }
}];

